const raw = $json.data;
const parsed = JSON.parse(raw);

return [
  {
    json: {
      sentimentLabel: parsed.label,
      probability: parsed.probability
    }
  }
];

/************************************************************
  FLUENCY METRICS EXTRACTOR
  - Word Count
  - Sentence Count
  - Filler Words Count
************************************************************/

// Get transcript from Webhook
const transcript = $("Webhook").item.json.body.transcript || "";

// --- Word Count ---
const wordCount = transcript.trim().length > 0 
  ? transcript.trim().split(/\s+/).length 
  : 0;

// --- Sentence Count ---
const sentenceCount = transcript
  .split(/[.!?]+/)
  .filter(s => s.trim().length > 0)
  .length;

// --- Filler Words Detection ---
const fillers = [
  "um",
  "uh",
  "like",
  "you know",
  "basically",
  "literally",
  "actually",
  "kinda",
  "sort of"
];

let fillerCount = 0;
for (const f of fillers) {
  const regex = new RegExp(`\\b${f}\\b`, "gi");
  const matches = transcript.match(regex);
  if (matches) fillerCount += matches.length;
}

// Return results
return [
  {
    json: {
      transcript,
      wordCount,
      sentenceCount,
      fillerCount
    }
  }
];

/************************************************************
  Rubric Generator - complete scoring (for n8n Function Node)
  Assumes node names:
    - Webhook (input)
    - LanguageTool (HTTP Request to LT)
    - Sentiment Parse (parses sentiment JSON -> { sentimentLabel, positiveProb })
    - Fluency Metrics (wordCount, sentenceCount, fillerCount)
************************************************************/

// Helper: safe getter
const getNode = (name) => $node[name] && $node[name].json ? $node[name].json : {};

// INPUTS
const transcript = $node["Webhook"].json.body && $node["Webhook"].json.body.transcript
  ? $node["Webhook"].json.body.transcript.toString()
  : "";

// LanguageTool matches array
const lt = $node["LanguageTool"].json;
const matches = lt && lt.matches ? lt.matches : [];
const grammarErrors = matches.length || 0;

// Sentiment parse output node must return:
// { sentimentLabel: "pos"|"neg"|"neutral", positiveProb: 0.0..1.0 }
const sentimentNode = getNode("Sentiment Parse");
const sentimentLabel = (sentimentNode.sentimentLabel || sentimentNode.label || "neutral").toString().toLowerCase();
const positiveProb = Number(sentimentNode.positiveProb ?? sentimentNode.probability?.pos ?? 0);

// Fluency metrics
const fm = getNode("Fluency Metrics");
const wordCount = Number(fm.wordCount || 0);
const sentenceCount = Number(fm.sentenceCount || 0);
const fillerCount = Number(fm.fillerCount || 0);

// Derived metrics
const totalWords = Math.max(1, wordCount); // avoid divide by zero
const errorsPer100 = (grammarErrors / totalWords) * 100; // grammar errors per 100 words

// ----- 1) Content & Structure (40) -----
// 1.A Salutation (0-5)
const txt = transcript.toLowerCase();

let salutationScore = 0;
let salutationKind = "none";
if (/i am excited|feeling great|excited to introduce/.test(txt)) { salutationScore = 5; salutationKind = "excellent"; }
else if (/good morning|good afternoon|good evening|good day|hello everyone/.test(txt)) { salutationScore = 4; salutationKind = "good"; }
else if (/\bhi\b|\bhello\b/.test(txt)) { salutationScore = 2; salutationKind = "normal"; }
else { salutationScore = 0; salutationKind = "none"; }

// 1.B Mandatory fields (Name, Age, School/Class, Family, Hobbies) each 4 points -> 20
// ----- Mandatory Fields (20 points) -----

// ----- Mandatory Fields (20 points) -----

const mandatory_name =
  /\b(my name is|myself|i am|i'm|this is)\s+[A-Za-z]+/i.test(transcript);

const mandatory_age =
  /\b(\d{1,2}\s*(years? old)?|age\s*[:]\s*\d{1,2})\b/i.test(transcript);

const mandatory_school =
  /\b(class\s*\d{1,2}|grade\s*\d{1,2}|studying in|school)\b/i.test(transcript);

const mandatory_family =
  /\b(family|parents|mother|father|brother|sister)\b/i.test(transcript);

const mandatory_hobbies =
  /\b(hobby|my hobby|i like|i love|i enjoy|free time|favorite)\b/i.test(transcript);

let mandatoryFound = 0;

if (mandatory_name) mandatoryFound++;
if (mandatory_age) mandatoryFound++;
if (mandatory_school) mandatoryFound++;
if (mandatory_family) mandatoryFound++;
if (mandatory_hobbies) mandatoryFound++;

const mandatoryScore = mandatoryFound * 4;   // MAX = 20

 // each 4 points, max 20

// 1.C Good-to-have (each 2 points) -> 10 total
let gthCount = 0;
if (/\b(i am from|i'm from|from)\b/i.test(transcript)) gthCount++;
if (/\b(dream|ambition|goal|want to become)\b/i.test(transcript)) gthCount++;
if (/\b(fun fact|interesting|unique)\b/i.test(transcript)) gthCount++;
if (/\b(strength|achievement|i won|medal|certificate)\b/i.test(transcript)) gthCount++;
if (/\b(family background)\b/i.test(transcript)) gthCount++;
const gthScore = Math.min(5, gthCount) * 2; // max 10

// 1.D Flow (5) -> check approximate order presence
// ----- Flow (max 5 points) -----

// Identify all important section positions in the text
const lc = transcript.toLowerCase();

const idx_salutation = lc.search(/hi|hello|good morning|good afternoon|good evening|good day|hello everyone|i am excited|feeling great/);
const idx_name       = lc.search(/my name is|myself|i am [a-z]+|i'm [a-z]+/);
const idx_mandatory  = lc.search(/(class|grade|school|years old|age|family|parents|hobby|i like|i enjoy|free time)/);
const idx_optional   = lc.search(/(dream|goal|ambition|interesting|fun fact|unique|achievement|strength)/);
const idx_closing    = lc.search(/thank you|thanks|that's all|thankyou/);

// Valid flow must be: salutation < name < mandatory < optional < closing

// Check that each exists (>=0)
const exists = (
  idx_salutation >= 0 &&
  idx_name >= 0 &&
  idx_mandatory >= 0 &&
  idx_optional >= 0 &&
  idx_closing >= 0
);

// Check order
const orderCorrect = (
  exists &&
  idx_salutation < idx_name &&
  idx_name < idx_mandatory &&
  idx_mandatory < idx_optional &&
  idx_optional < idx_closing
);

// Score
const flowScore = orderCorrect ? 5 : 0;


const contentTotal = salutationScore + mandatoryScore + gthScore + flowScore; // max 5 + 20 + 10 + 5 = 40

// ----- 2) Speech Rate (10) -----
// If you provide duration in seconds in Webhook body -> use it. Else assume 60s.
const durationSeconds = Number($node["Webhook"].json.body.duration || $node["Webhook"].json.duration || 60);
const wpm = Math.round((totalWords / Math.max(1, durationSeconds)) * 60);

let wpmScore = 0;
if (wpm > 161) wpmScore = 2;
else if (wpm >= 141) wpmScore = 6;
else if (wpm >= 111) wpmScore = 10;
else if (wpm >= 81) wpmScore = 6;
else wpmScore = 2;

// ----- 3) Grammar (10) -----
// ----- Grammar (10 points) -----

// Ensure wordCount is never 0
const wc = Math.max(1, wordCount);

// Extract grammar errors safely
const ge = Number(grammarErrors || 0);

// errors per 100 words
const errorsPerhund = (ge / wc) * 100;

// ratio = 1 - min(errorsPer100/10, 1)
const ratio = 1 - Math.min(errorsPerhund / 10, 1);

let grammarScore = 0;

if (ratio >= 0.90) {
  grammarScore = 10;
} else if (ratio >= 0.70) {
  grammarScore = 8;
} else if (ratio >= 0.50) {
  grammarScore = 6;
} else if (ratio >= 0.30) {
  grammarScore = 4;
} else {
  grammarScore = 2;
}

// Keep values rounded nicely
const grammarBlock = {
  grammarErrors: ge,
  errorsPer100: Number(errorsPer100.toFixed(2)),
  ratio: Number(ratio.toFixed(3)),
  grammarScore
};
grammar: grammarBlock

// ----- 4) Vocabulary richness (TTR) (10) -----
const tokens = transcript.trim().split(/\s+/).filter(t => t.trim().length>0);
const distinct = Array.from(new Set(tokens.map(t=>t.replace(/[^\w]/g,"").toLowerCase()).filter(Boolean)));
const TTR = distinct.length / Math.max(1, tokens.length);

let vocabScore = 0;
if (TTR >= 0.9) vocabScore = 10;
else if (TTR >= 0.7) vocabScore = 8;
else if (TTR >= 0.5) vocabScore = 6;
else if (TTR >= 0.3) vocabScore = 4;
else vocabScore = 2;

// ----- 5) Clarity - Filler Rate (15) -----
const fillerRate = (fillerCount / Math.max(1, totalWords)) * 100;
let clarityScore = 0;
if (fillerRate <= 3) clarityScore = 15;
else if (fillerRate <= 6) clarityScore = 12;
else if (fillerRate <= 9) clarityScore = 9;
else if (fillerRate <= 12) clarityScore = 6;
else clarityScore = 3;

// ----- 6) Engagement - sentiment (15) -----
// We'll use positiveProb (0..1)
let engagementScore = 0;
if (positiveProb >= 0.9) engagementScore = 15;
else if (positiveProb >= 0.7) engagementScore = 12;
else if (positiveProb >= 0.5) engagementScore = 9;
else if (positiveProb >= 0.3) engagementScore = 6;
else engagementScore = 3;

// ----- Totals -----
const grammarInfo = { grammarErrors, errorsPer100: Number(errorsPer100.toFixed(2)), ratio: Number(ratio.toFixed(3)) };
const scores = {
  content: { salutationScore, mandatoryScore, gthScore, flowScore, total: contentTotal },
  speech: { wpm, wpmScore },
  grammar: { ...grammarInfo, grammarScore },
  vocabulary: { TTR: Number(TTR.toFixed(3)), vocabScore },
  clarity: { fillerCount, fillerRate: Number(fillerRate.toFixed(2)), clarityScore },
  engagement: { sentimentLabel, positiveProb: Number(positiveProb.toFixed(3)), engagementScore }
};

const totalScore = scores.content.total + scores.speech.wpmScore + scores.grammar.grammarScore + scores.vocabulary.vocabScore + scores.clarity.clarityScore + scores.engagement.engagementScore;

// Build comments (short)
const comments = {
  contentComment: (contentTotal>=30)?"Very good content structure":(contentTotal>=20)?"Good":"Needs improvement",
  languageComment: grammarScore>=8 ? "Strong grammar" : grammarScore>=5 ? "Acceptable grammar" : "Weak grammar",
  vocabComment: vocabScore>=8 ? "Rich vocabulary" : vocabScore>=5 ? "Moderate vocabulary" : "Limited vocabulary",
  fluencyComment: clarityScore>=12 ? "Clear delivery" : "Could reduce fillers",
  engagementComment: engagementScore>=12 ? "Engaging tone" : "Less enthusiastic"
};

// Output JSON
return [
  {
    json: {
      transcript,
      wordCount: totalWords,
      sentenceCount,
      fillerCount,
      scores,
      totalScore,
      comments
    }
  }
];
